async def act(page):
    """
    Dismiss any visible popup overlay and click the Post Comment button inside the
    main region on the current article page. Uses accessibility-role-centric
    selectors and guarded counts to avoid indexing errors.
    """
    import asyncio

    async def safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # 1) Attempt to dismiss an obvious popup by clicking a close-like button.
    # Try a set of common accessible names first, then scan all buttons for
    # aria-label/title/inner text that looks like a close affordance.
    close_names = ["Close", "close", "Close this popup", "Dismiss", "×", "✕", "✖", "x", "X"]
    dismissed = False

    for name in close_names:
        try:
            btn = page.get_by_role("button", name=name)
            if await safe_count(btn) > 0:
                try:
                    await btn.first.click()
                    await asyncio.sleep(0.25)
                    dismissed = True
                    break
                except Exception:
                    # ignore a click failure and continue
                    pass
        except Exception:
            pass

    if not dismissed:
        # Scan all page-level buttons and inspect attributes/text for a close-like label
        all_buttons = page.get_by_role("button")
        total = await safe_count(all_buttons)
        for i in range(total):
            b = all_buttons.nth(i)
            try:
                aria = (await b.get_attribute("aria-label")) or ""
            except Exception:
                aria = ""
            try:
                title = (await b.get_attribute("title")) or ""
            except Exception:
                title = ""
            try:
                txt = (await b.inner_text()) or ""
            except Exception:
                txt = ""
            combined = (aria + " " + title + " " + txt).strip().lower()
            if any(token in combined for token in ("close", "dismiss", "×", "✕", "✖", " x ", "\u00d7")):
                try:
                    await b.click()
                    await asyncio.sleep(0.25)
                    dismissed = True
                    break
                except Exception:
                    # continue scanning
                    pass

    # 2) Locate the main region and ensure an article/form is present
    main_region = page.get_by_role("main")
    if await safe_count(main_region) == 0:
        raise Exception("No main region present on the page")

    # 3) Attempt to find a clearly-labelled 'Post Comment' submit button under main
    candidate_names = ["Post Comment", "Submit Comment", "Submit", "Post", "Send", "Send Comment"]

    submit_btn = None
    for name in candidate_names:
        loc = main_region.get_by_role("button", name=name)
        if await safe_count(loc) > 0:
            submit_btn = loc.first
            break

    # 4) If not found by exact name, inspect buttons inside main and pick one whose
    # visible text strongly suggests it's the comment submit (contains both 'post' and 'comment',
    # or equals 'post').
    if submit_btn is None:
        main_buttons = main_region.get_by_role("button")
        mb_count = await safe_count(main_buttons)
        for i in range(mb_count):
            b = main_buttons.nth(i)
            try:
                txt = (await b.inner_text()).strip().lower()
            except Exception:
                txt = ""
            if not txt:
                # try aria-label/title as a fallback
                try:
                    txt = ((await b.get_attribute("aria-label")) or "").strip().lower()
                except Exception:
                    txt = ""
            if txt:
                if ("post" in txt and "comment" in txt) or txt == "post comment" or txt == "post":
                    submit_btn = b
                    break

    # 5) Page-level fallback: choose the first button on the page if nothing in main matched
    if submit_btn is None:
        page_buttons = page.get_by_role("button")
        if await safe_count(page_buttons) > 0:
            submit_btn = page_buttons.first

    if submit_btn is None:
        raise Exception("Could not find any button to submit the comment")

    # 6) Click the chosen submit button. This is the final action (may navigate/submit).
    try:
        await submit_btn.click()
    except Exception as e:
        # If the click fails, surface a clear error
        raise Exception(f"Failed to click submit button: {e}")

    # Allow a short grace period for the submission to process
    try:
        await page.wait_for_load_state("networkidle", timeout=4000)
    except Exception:
        await asyncio.sleep(1)

